// Dotted world map for the "world-map" feature, sampled at authoring time from
// world-atlas@2.0.2 (land-110m / countries-110m, Natural Earth public-domain
// data) with d3-geo's Natural Earth projection, centred on 11°E and cropped
// to -57°…79°. 4933 land dots on a 5-unit square grid.
//
// Sampling: a 5-unit square grid over the projected map; a dot is land when
// at least 2 of 5 sub-samples (centre + quarter points) fall inside land-110m.
// Authoring-time only (the site build stays zero-dependency): in a scratch dir,
// npm i world-atlas@2.0.2 topojson-client@3.1.0 d3-geo@3.1.1 and re-run the
// generator described in the world-map feature notes.
//
// Encoding: rows joined by "|", each "<row>:<col>+<count>,…" — a run of
// <count> consecutive land dots starting at <col>. Dot (r, c) sits at
// (MAP.ox + c * MAP.step, MAP.oy + r * MAP.step) in a 1000 × 424 viewBox.

export const MAP = { w: 1000, h: 424, step: 5, ox: 2.5, oy: 4.5, cols: 200, rows: 84 };

const K = 182.789644, TX = 500, TY = 242.094419, ROT = -11;

// Natural Earth I (Šavrič et al.), identical to d3.geoNaturalEarth1 with the
// rotation, scale and translation used to sample the dots.
export function project(lon, lat) {
  let l = lon + ROT; l = ((l + 540) % 360) - 180;
  const lam = l * Math.PI / 180, phi = lat * Math.PI / 180, p2 = phi * phi, p4 = p2 * p2;
  const x = lam * (0.8707 - 0.131979 * p2 + p4 * (-0.013791 + p4 * (0.003971 * p2 - 0.001529 * p4)));
  const y = phi * (1.007226 + p2 * (0.015085 + p4 * (-0.044475 + 0.028874 * p2 - 0.005916 * p4)));
  return [TX + K * x, TY - K * y];
}

export function decode(s) {
  return s ? s.split('|').map((row) => {
    const [r, runs] = row.split(':');
    return [Number(r), runs.split(',').map((x) => x.split('+').map(Number))];
  }) : [];
}

